1	package com.example.starter.service;
2	
3	import com.example.starter.domain.AdjustmentTask;
4	import com.example.starter.domain.HeatingUnit;
5	import com.example.starter.domain.TemperatureReading;
6	import com.example.starter.repository.AdjustmentTaskRepository;
7	import com.example.starter.repository.LateTemperatureEventRepository;
8	import com.example.starter.repository.TemperatureRepository;
9	import com.example.starter.repository.UnitRepository;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	import java.math.BigDecimal;
14	import java.math.RoundingMode;
15	import java.time.Clock;
16	import java.time.Instant;
17	import java.util.ArrayList;
18	import java.util.LinkedHashMap;
19	import java.util.List;
20	import java.util.Map;
21	import java.util.Optional;
22	
23	/**
24	 * 运行监测与失衡判定：温度上报（含归档后迟到事件）、站内温度分布与平衡判定。
25	 */
26	@Service
27	public class BalanceService {
28	
29	    /** 平衡阈值：站内回水温度最高最低差不超过 2℃（恰 2℃ 合格）。 */
30	    public static final BigDecimal BALANCE_THRESHOLD = new BigDecimal("2");
31	
32	    private final UnitRepository unitRepository;
33	    private final TemperatureRepository temperatureRepository;
34	    private final AdjustmentTaskRepository taskRepository;
35	    private final LateTemperatureEventRepository lateEventRepository;
36	    private final Clock clock;
37	
38	    public BalanceService(UnitRepository unitRepository,
39	                          TemperatureRepository temperatureRepository,
40	                          AdjustmentTaskRepository taskRepository,
41	                          LateTemperatureEventRepository lateEventRepository,
42	                          Clock clock) {
43	        this.unitRepository = unitRepository;
44	        this.temperatureRepository = temperatureRepository;
45	        this.taskRepository = taskRepository;
46	        this.lateEventRepository = lateEventRepository;
47	        this.clock = clock;
48	    }
49	
50	    /**
51	     * 单条温度上报请求。
52	     *
53	     * @param unitId      单元 ID
54	     * @param temperature 回水温度，单位 ℃
55	     * @param recordedAt  采集时间（UTC）
56	     */
57	    public record ReadingCommand(long unitId, BigDecimal temperature, Instant recordedAt) {
58	    }
59	
60	    /**
61	     * 上报结果。
62	     *
63	     * @param accepted   正常入库条数
64	     * @param lateEvents 归档后迟到、仅登记事件的条数
65	     */
66	    public record ReadingResult(int accepted, int lateEvents) {
67	    }
68	
69	    /**
70	     * 批量上报回水温度。归档任务的采集时间早于归档时间的迟到数据只记迟到事件，不入库。
71	     */
72	    @Transactional
73	    public ReadingResult submitReadings(long stationId, List<ReadingCommand> readings) {
74	        Map<Long, HeatingUnit> units = new LinkedHashMap<>();
75	        for (HeatingUnit unit : unitRepository.findByStationId(stationId)) {
76	            units.put(unit.id(), unit);
77	        }
78	        Optional<AdjustmentTask> archived = taskRepository.findLatestArchivedByStationId(stationId);
79	        Instant now = clock.instant();
80	        int accepted = 0;
81	        int late = 0;
82	        for (ReadingCommand reading : readings) {
83	            if (!units.containsKey(reading.unitId())) {
84	                throw new NotFoundException("单元不存在或不属于该换热站: unitId=" + reading.unitId());
85	            }
86	            if (archived.isPresent() && reading.recordedAt().isBefore(archived.get().archivedAt())) {
87	                lateEventRepository.insert(reading.unitId(), archived.get().id(),
88	                        reading.temperature(), reading.recordedAt(), now);
89	                late++;
90	            } else {
91	                temperatureRepository.insert(reading.unitId(), reading.temperature(),
92	                        reading.recordedAt(), now);
93	                accepted++;
94	            }
95	        }
96	        return new ReadingResult(accepted, late);
97	    }
98	
99	    /**
100	     * 单元温度分布项。
101	     *
102	     * @param unitId       单元 ID
103	     * @param unitCode     单元编码
104	     * @param temperature  最新回水温度，单位 ℃；无数据时为 null
105	     * @param recordedAt   采集时间（UTC）；无数据时为 null
106	     * @param classification 失衡分类：UNDERFLOW 欠流 / OVERFLOW 过流；平衡或无数据时为 null
107	     */
108	    public record UnitTemperature(long unitId, String unitCode, BigDecimal temperature,
109	                                  Instant recordedAt, AdjustmentTask.ImbalanceType classification) {
110	    }
111	
112	    /**
113	     * 站内平衡判定结果。
114	     *
115	     * @param stationId 换热站 ID
116	     * @param units     各单元温度分布
117	     * @param maxTemp   最高回水温度，单位 ℃
118	     * @param minTemp   最低回水温度，单位 ℃
119	     * @param diff      最高最低差，单位 ℃
120	     * @param balanced  是否平衡：diff 不超过 2℃（恰 2℃ 合格）
121	     */
122	    public record BalanceView(long stationId, List<UnitTemperature> units,
123	                              BigDecimal maxTemp, BigDecimal minTemp, BigDecimal diff,
124	                              boolean balanced) {
125	    }
126	
127	    /**
128	     * 计算换热站在指定时间点（含）的温度分布与平衡判定。
129	     */
130	    @Transactional(readOnly = true)
131	    public BalanceView evaluateBalance(long stationId, Instant asOf) {
132	        List<HeatingUnit> units = unitRepository.findByStationId(stationId);
133	        if (units.isEmpty()) {
134	            throw new NotFoundException("换热站不存在或无单元: stationId=" + stationId);
135	        }
136	        Map<Long, TemperatureReading> latest = new LinkedHashMap<>();
137	        for (TemperatureReading reading : temperatureRepository.findLatestPerUnit(stationId, asOf)) {
138	            latest.put(reading.unitId(), reading);
139	        }
140	        BigDecimal sum = BigDecimal.ZERO;
141	        int count = 0;
142	        for (TemperatureReading reading : latest.values()) {
143	            sum = sum.add(reading.temperature());
144	            count++;
145	        }
146	        BigDecimal avg = count == 0 ? null
147	                : sum.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_UP);
148	
149	        List<UnitTemperature> items = new ArrayList<>();
150	        BigDecimal max = null;
151	        BigDecimal min = null;
152	        for (HeatingUnit unit : units) {
153	            TemperatureReading reading = latest.get(unit.id());
154	            AdjustmentTask.ImbalanceType classification = null;
155	            if (reading != null) {
156	                BigDecimal temp = reading.temperature();
157	                max = max == null || temp.compareTo(max) > 0 ? temp : max;
158	                min = min == null || temp.compareTo(min) < 0 ? temp : min;
159	                if (avg != null && temp.compareTo(avg) < 0) {
160	                    classification = AdjustmentTask.ImbalanceType.UNDERFLOW;
161	                } else if (avg != null && temp.compareTo(avg) > 0) {
162	                    classification = AdjustmentTask.ImbalanceType.OVERFLOW;
163	                }
164	                items.add(new UnitTemperature(unit.id(), unit.code(), temp,
165	                        reading.recordedAt(), classification));
166	            } else {
167	                items.add(new UnitTemperature(unit.id(), unit.code(), null, null, null));
168	            }
169	        }
170	        BigDecimal diff = max == null ? null : max.subtract(min);
171	        boolean balanced = diff != null && diff.compareTo(BALANCE_THRESHOLD) <= 0;
172	        return new BalanceView(stationId, items, max, min, diff, balanced);
173	    }
174	}
