COMMENT ON COLUMN heating_unit.name IS '单元名称';

CREATE TABLE IF NOT EXISTS valve (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    unit_id BIGINT NOT NULL REFERENCES heating_unit (id),
    opening_percent DECIMAL(5,2) NOT NULL,
