        assertThat(seal.status()).isEqualTo(ValveSeal.SealStatus.ACTIVE);
        assertThat(seal.version()).isEqualTo(1);
        assertThat(seal.valveVersion()).isEqualTo(0);
        assertThat(seal.sealedAt()).isEqualTo(T0);

        // 同键同参重放返回首次冻结结果
