        assertThat(replay.id()).isEqualTo(seal.id());
        assertThat(countOf("valve_seal")).isEqualTo(1);

        // 同键异参 409
        assertThatThrownBy(() -> registerSeal(1L, "req-seal-r", "SEAL-101"))
                .isInstanceOf(ConflictException.class);
