        assertThatThrownBy(() -> sealService.reseal(
                1L, "req-rs-badver", 9, "SEAL-901", "甲", "乙", 1))
                .isInstanceOf(ConflictException.class);

        ValveSeal newSeal = sealService.reseal(1L, "req-rs-ok", 1, "SEAL-901", "甲", "乙", 1);
