                .andExpect(jsonPath("$.quotaTotal").value(2))
                .andExpect(jsonPath("$.quotaUsed").value(0));

        // 受控调节：原子更新开度、写版本并消费一次额度
        mockMvc.perform(post("/api/unseals/1/adjustments")
                        .contentType(MediaType.APPLICATION_JSON)
