                .andExpect(jsonPath("$.version").value(3));

        // 复封：两名不同人员核对当前开度版本（1），登记新铅封号
        mockMvc.perform(post("/api/valves/1/reseals")
                        .contentType(MediaType.APPLICATION_JSON)
