                .andExpect(jsonPath("$[0].status").value("RESEALED"))
                .andExpect(jsonPath("$[1].sealNo").value("SEAL-002"))
                .andExpect(jsonPath("$[1].status").value("ACTIVE"));
    }

    @Test
    void 错误语义_参数非法400_对象不存在404_同键异参409() throws Exception {
        // 参数非法 400：缺少 sealNo
